{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure compliance with applicable financial regulations and standards to guarantee legal accountability.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall implement flexible user access controls that allow for concurrency while ensuring authorized modifications.",
      "quality_axes": ["Trustworthiness|Efficiency|Responsibility"],
      "derived_from": ["RES-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall maintain a streamlined audit trail of all transactions for a minimum of 5 years.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-03", "TRU-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall implement a tiered processing approach prioritizing accuracy in initial entries while maintaining performance.",
      "quality_axes": ["Efficiency|Safety"],
      "derived_from": ["EFF-01", "SAF-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall ensure the validation process for currency conversions prioritizes accuracy and energy efficiency.",
      "quality_axes": ["Efficiency|Sustainability|Safety"],
      "derived_from": ["EFF-06", "SAF-06", "GRN-01"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall integrate security checks within the validation framework to maintain data integrity.",
      "quality_axes": ["Trustworthiness|Safety"],
      "derived_from": ["TRU-04", "SAF-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall implement adaptive access controls that adjust based on system load to ensure performance.",
      "quality_axes": ["Efficiency|Trustworthiness"],
      "derived_from": ["RES-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The system shall evaluate performance and energy consumption of validation processes regularly.",
      "quality_axes": ["Efficiency|Sustainability"],
      "derived_from": ["EFF-01", "GRN-01"],
      "kaos_level": "tactical",
      "parent": null
    }
  ],
